  records = [];
  selected = null;
  dialog.close();
  dialog.innerHTML = "";
}
// Shared-device/privacy reset clears in-memory values and invalidates photo callbacks.
// It does not erase a page-one draft already saved on the server. No localStorage used.
function clearIntake() {
  draftToken = null;
  draftDeadline = null;
  timeoutNotice = "";
  data = defaults();
  photo = null;
  step = 0;
  receipt = null;
