  const toggle = surface.querySelector("#form-view-toggle");
  toggle.innerHTML =
    (sheetView ? webIcon : sheetIcon) +
    "<span>" +
    (sheetView ? "Web-style form" : "Smartsheet-style view") +
    "</span>";
