// Browser resizing is a convenience, not the security boundary; the server decodes
// and bounds the image independently. Photos are never sent in page-one drafts.
async function loadPhoto(file) {
  if (!file) return;
  if (
    !["image/jpeg", "image/png", "image/webp"].includes(file.type) ||
    file.size > 10 * 1024 * 1024
  ) {
    showError("Choose a JPG, PNG, or WebP image under 10 MB.");
    return;
  }
  const generation = ++photoVersion;
  photoBusy = true;
  const next = document.querySelector("#next");
  if (next) next.disabled = true;
  try {
    const url = URL.createObjectURL(file);
    try {
      const img = new Image();
      img.src = url;
      await img.decode();
      if (img.naturalWidth * img.naturalHeight > 20_000_000)
        throw new Error("Please choose a photo smaller than 20 megapixels.");
      const ratio = Math.min(
          1,
          1000 / img.naturalWidth,
          1000 / img.naturalHeight,
