        canvas = document.createElement("canvas");
      canvas.width = Math.round(img.naturalWidth * ratio);
      canvas.height = Math.round(img.naturalHeight * ratio);
      canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
      if (generation !== photoVersion) return;
      photo = canvas.toDataURL("image/jpeg", 0.75);
      if (photo.length > 800000) {
        photo = null;
        throw new Error("Photo is still too large. Try a smaller image.");
      }
      renderIntake();
      toast("Photo added. Location metadata removed.");
    } finally {
      URL.revokeObjectURL(url);
    }
  } catch (e) {
    showError(e.message || "Unable to read that image.");
  } finally {
    photoBusy = false;
    const button = document.querySelector("#next");
    if (button) button.disabled = false;
  }
}
// Page-one Continue durably saves the allowlisted snapshot, then starts the original
// 20-minute window. Final submit is a separate operation with a full acknowledgment.
// Network errors are not proof of a saved request; only a successful response is.
async function submitStep(e) {
  e.preventDefault();
  if (submitting || photoBusy) return;
  if (timedOut()) {
    expireIntake();
    return;
  }
  if (step === 0) {
    const generation = photoVersion;
    draftToken ||= newDraftToken();
    submitting = true;
    const next = main.querySelector("#next");
    next.disabled = true;
    next.textContent = "Saving page one…";
    try {
      const saved = await api("drafts", "POST", {
        draftToken,
        data: Object.fromEntries(
          [
            "name",
            "email",
            "phone",
            "department",
            "affiliation",
            "sponsor",
            "sponsorEmail",
            "badge",
          ].map((key) => [key, data[key]]),
        ),
        website: main.querySelector("[name=website]").value,
      });
      if (generation !== photoVersion) return;
      draftDeadline =
        Date.now() +
        (Date.parse(saved.expiresAt) - Date.parse(saved.serverNow));
      if (timedOut()) {
        expireIntake();
        return;
      }
      timeoutNotice = "";
      step = 1;
      renderIntake();
      focusHeading();
    } catch (err) {
      if (generation !== photoVersion) return;
      if (err.status === 410) expireIntake();
      else {
        showError(err.message);
        next.disabled = false;
        next.textContent = "Continue →";
      }
    } finally {
      submitting = false;
    }
    return;
  }
  if (step === 1) {
    if (!data.accessTypes.length) {
      showError("Choose at least one access type.");
      return;
    }
    if (data.endDate < data.startDate) {
      showError("End date must follow the start date.");
      return;
    }
    if (
      (Date.parse(data.endDate) - Date.parse(data.startDate)) / 86400000 >
      366
    ) {
      showError("Choose an access window of one year or less.");
      return;
    }
  }
  if (step < 3) {
    step++;
    renderIntake();
    focusHeading();
    return;
  }
  submitting = true;
  const button = document.querySelector("#next");
  button.disabled = true;
  button.textContent = "Submitting…";
  try {
    const result = await api("requests", "POST", {
      draftToken,
      data,
      photo,
      website: document.querySelector("[name=website]").value,
    });
    clearIntake();
    receipt = result;
    if (kiosk) {
      renderReceipt(result);
      setTimeout(() => {
        if (kiosk && receipt === result) {
          clearIntake();
          renderIntake();
        }
      }, 45000);
    } else navigate("#receipt/" + result.receipt);
  } catch (err) {
    if (err.status === 410) {
      expireIntake();
      return;
    }
    showError(err.message);
    button.disabled = false;
    button.textContent = "Submit request →";
  } finally {
    submitting = false;
  }
}
async function startKiosk() {
  try {
    await api("logout", "POST", {});
  } catch (e) {
    if (e.status !== 401) {
      showError(
        "Could not sign staff out. Please retry before handing over the iPad.",
      );
      return;
    }
  }
  clearStaff();
  clearIntake();
  kiosk = true;
  lastActivity = Date.now();
  navigate("#kiosk");
}
function renderReceipt(result) {
