/* REVIEW NOTE: visual styling only. Status colors and hidden buttons are not
   authorization controls; all decisions must pass the server-side policy checks. */
:root {
  --ink: #183b40;
  --ink-dark: #112e33;
  --teal: #257267;
  --paper: #f5f3ed;
  --white: #fff;
  --muted: #677572;
  --line: #dedfd7;
  --gold: #b98d55;
  --soft: #eaf2ed;
  --danger: #a23f35;
  --radius: 18px;
  font-family:
    Inter,
    ui-sans-serif,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  color: var(--ink);
  background: var(--paper);
  font-synthesis: none;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
button,
input,
select,
textarea {
  font: inherit;
}
button,
a,
input,
select,
textarea {
  touch-action: manipulation;
}
button,
a {
  -webkit-tap-highlight-color: transparent;
}
a {
  color: inherit;
}
button {
  cursor: pointer;
}
button:disabled {
  opacity: 0.55;
  cursor: wait;
}
button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid #bc8a45;
  outline-offset: 4px;
}
.skip {
  position: fixed;
  top: -80px;
  left: 20px;
  background: white;
  padding: 16px;
  z-index: 99;
}
.skip:focus {
  top: 12px;
}
.demo-strip {
  background: var(--ink-dark);
  color: #f3f0e6;
  padding: 10px 24px;
  font-size: 11px;
  letter-spacing: 0.035em;
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: center;
}
.demo-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #d7b17a;
}
.strip-divider {
  opacity: 0.4;
  margin: 0 3px;
}
.site-header {
  max-width: 1280px;
  padding: 27px 42px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: auto;
  border-bottom: 1px solid var(--line);
}
.brand {
  display: flex;
  align-items: center;
  gap: 13px;
  text-decoration: none;
}
.brand-mark {
  width: 48px;
  height: 48px;
  flex-shrink: 0;
}
.brand strong {
  font-family: Georgia, serif;
  font-size: 27px;
  font-weight: 500;
  letter-spacing: -0.9px;
}
.brand small {
  display: block;
  font-size: 8px;
  letter-spacing: 1.5px;
  margin-top: 5px;
  font-weight: 650;
}
nav {
  display: flex;
  gap: 30px;
  align-items: center;
}
nav a {
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  padding: 10px 0;
}
nav a.active {
  color: var(--teal);
  border-bottom: 2px solid var(--teal);
}
nav span {
  margin-left: 10px;
}
main {
  max-width: 1196px;
  margin: auto;
  padding: 46px 0 64px;
}
.eyebrow {
  text-transform: uppercase;
  letter-spacing: 2px;
  font-size: 10px;
  font-weight: 750;
  color: var(--teal);
  display: flex;
  align-items: center;
  gap: 10px;
}
.eyebrow:before {
  content: "";
  width: 25px;
  height: 2px;
  background: var(--gold);
}
h1,
h2,
h3,
p {
  margin-top: 0;
}
h1 {
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(38px, 4.6vw, 58px);
  line-height: 1.07;
  letter-spacing: -2px;
  font-weight: 400;
  margin: 17px 0;
}
h1 em {
  color: var(--teal);
  font-style: normal;
}
h2 {
  font-size: 23px;
  letter-spacing: -0.6px;
  margin-bottom: 9px;
}
h3 {
  font-size: 15px;
  margin-bottom: 10px;
}
p {
  line-height: 1.65;
  color: var(--muted);
  font-size: 14px;
}
.hero {
