}
.service-note strong {
  display: block;
  font-size: 15px;
  margin: 9px 0;
}
.service-note p {
  font-size: 12px;
  max-width: 225px;
  margin: 0;
}
.service-note .tiny-label {
  margin-top: 16px;
  font-size: 11px;
  color: var(--teal);
}
.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 302px;
  gap: 24px;
